find:
if trimmed.is_empty() || !trimmed.bytes().all(|b| b.is_ascii_digit()) {
    return None;
}
trimmed.parse::<u64>().ok().map(|s| s.saturating_mul(1_000))

replace:
if trimmed.is_empty() {
    return None;
}
trimmed
    .parse::<f64>()
    .ok()
    .map(|seconds| (seconds.max(0.0) * 1_000.0) as u64)
